// ai-agents/harness/src/routines/test-gaps.ts: sketch of Meta's ACH roles; the test writer is the one writer.
// Runs in the harness inside the VM; the planter and the filter are helper sessions.
export async function fillGaps(vm: Vm, module: string): Promise<NewTest[]> {
  const lines = await vm.uncoveredChangedLines(module, { sinceDays: 30 });  // coverage report ∩ recent changes
  const mutants = await vm.helper({ role: "planter", model: "claude-sonnet-5-5", effort: "medium",
                                    task: "plant one small realistic bug per behaviour", lines, n: 8 });
  const real: Mutant[] = [];
  for (const m of mutants) {
    if ((await vm.builds(m)) && !(await vm.helper({ role: "filter", task: "is this mutant equivalent?", mutant: m }))) {
      real.push(m);
    }
  }
  const kept: NewTest[] = [];
  for (const m of real) {
    const test = await vm.session({ task: "add-tests", target: m.behaviour, rules: ["test what the user or API caller sees"] });
    if ((await vm.failsOn(test, { mutant: m })) && (await vm.passesOn(test, { clean: true }))) {
      kept.push(test);  // kept only if it catches its planted bug
    }
  }
  return kept.slice(0, 5);  // a small PR: at most 5 tests per run
}

// ai-agents/harness/src/routines/duplicates.ts: sketch: weekly "abstraction police"; many readers, one writer.
// Runs in the harness inside the lite VM.
const FINDERS: Record<"fe" | "be", string> = {
  fe: "npx jscpd --min-tokens 60 --reporters json --output /tmp/jscpd frontend/src",
  be: "pylint --disable=all --enable=duplicate-code --min-similarity-lines=12 --output-format=json cloud/rhinoCloud/rhinoCore",
};

export async function sweep(vm: Vm, area: "fe" | "be"): Promise<Proposal | undefined> {
  const clones = parseClones(area, await vm.exec("bash", ["-c", FINDERS[area]], { cwd: "/work/fcp" }));
  const top = clones.sort((a, b) => b.tokens * b.copies.length - a.tokens * a.copies.length).slice(0, 10);
  const verdicts = await Promise.all(top.map((clone) =>  // parallel read-only judges
    vm.helper({ model: "claude-sonnet-5-5", effort: "medium", task: "is-real-duplication", clone })));
  const real = top.filter((_, i) => verdicts[i].real && verdicts[i].sameReasonToChange);  // coincidences stay apart
  if (real.length === 0) {
    return undefined;
  }
  return vm.session({ task: "merge-duplicates", clone: real[0],  // one writer, one proposal a week
                      rules: ["no behaviour change", "existing tests unchanged and green"] });
}

// ai-agents/orchestrator/src/triggers/security-findings.ts: sketch: only findings a version bump can fix
export async function fixableFindings(repo: string): Promise<Finding[]> {
  const found: Finding[] = [];
  for (const alert of await broker.github.dependabotAlerts(repo, { state: "open" })) {  // read-only scope
    const fixed = alert.security_vulnerability.first_patched_version;  // GitHub's JSON field names
    if (fixed) {
      found.push({ source: "dependabot", repo, url: alert.html_url, package: alert.dependency.package.name,
                   manifest: alert.dependency.manifest_path, fixed: fixed.identifier });
    }
  }
  for (const issue of await broker.jira.search(VANTA_FINDINGS_JQL)) {  // Vanta findings that Vanil files; JQL from Ronen
    if (issue.fixedVersion) {  // no fixed release yet → stays with people
      found.push(Finding.fromJira(issue));
    }
  }
  return found;
}

export function workflowId(f: Finding): string {
  return `sec:${f.repo}:${f.package}@${f.fixed}`;  // one run per package and fixed version
}
